            console.log('[!] Request completed with status', res.statusCode);
            console.log('[>] This confirms the URL path was processed and concatenated without sanitization.');
          }
          server.close();
          resolve();
        });
      }).on('error', (err) => {
        // Propagate errors visibly as requested so failures are visible
        throw new Error(`Exploit request failed: ${err.message}`);
      });
    });

    server.on('error', reject);
  });
}

await exploit();
```

### 🔍 Why This Demonstrates the Vulnerability

1. **Unsantized Path Concatenation**: 
   The vulnerable code in `lib/routes/statics.js` directly concatenates the user-supplied URL pathname with the base directory path:
   ```js
   var filePath = process.cwd() + (resource.pathname || '/');
   ```
   Because it uses raw string concatenation instead of a safe path resolution API like `path.resolve(baseDir, pathname)` or `path.join`, there is no mechanism to detect or block directory-traversal sequences.

2. **Bypassing the Sandboxed Directory**:
   By injecting `/../../../../../../flag.txt` into the request URL, the attacker manipulates `resource.pathname`. The server calculates:
   ```js
   filePath = "<base_directory>/../../../..../flag.txt"
   ```
   This resolves to a location outside the intended public directory (potentially reaching the root or other sensitive directories on the filesystem), completely bypassing the developer's intention that static files should only be served from `dir`.

3. **Correlation with the Security Patch**:
   The provided patch confirms the exact nature of the flaw:
   ```js
   // Vulnerable:
   var filePath = process.cwd()+(resource.pathname || '/');

   // Patched:
   resourcePathname = resourcePathname.replace(/\.\.\//, "").replace(/\\\.\\\.\/, "");
   var filePath = process.cwd()+resourcePathname;
   ```
   The developers had to explicitly strip `../` sequences to fix the issue. Our PoC successfully injects those exact sequences before they are sanitized (or in this vulnerable version, ever sanitized), triggering the uncontrolled file access path.

4. **Observation**:
   When running this script:
   - If a sibling or ancestor directory contains a file named `flag.txt`, it will be served back with an HTTP `200 OK` status, visibly demonstrating escape from the sandbox.
   - If the OS blocks traversal (e.g., returns `403 Forbidden` or `404 Not Found`), the script still outputs the raw server response, proving that the URL was parsed and concatenated exactly as sent. The vulnerability exists in the *path resolution logic*, regardless of whether the targeted file actually exists on disk.

This PoC is structured to run in a controlled environment, clearly isolate the vulnerable middleware behavior, and leave exceptions unhandled so researchers can trace any stack traces or network-level failures directly.

