    const VULNERABLE_TIME_UNITS_PATTERN = `(?:${SINGLE_TIME_UNIT_PATTERN_NO_CAPTURE})(?:\s*,?\s*${SINGLE_TIME_UNIT_PATTERN_NO_CAPTURE})*`;

